function solve(grid) {
  const m = grid.length;
  if (!m) return 0;
  const n = grid[0].length;
  let best = 0;
  function dfs(i, j) {
    if (i < 0 || j < 0 || i >= m || j >= n || grid[i][j] !== 1) return 0;
    grid[i][j] = 0;
    return 1 + dfs(i + 1, j) + dfs(i - 1, j) + dfs(i, j + 1) + dfs(i, j - 1);
  }
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] === 1) best = Math.max(best, dfs(i, j));
    }
  }
  return best;
}
